var o=[{title:`Superfici comuni`,text:`Un pavimento solido e piano offre un appoggio stabile per la maggior parte dei movimenti di forza. Una moquette spessa e morbida può far oscillare durante il lavoro su una gamba, e le piastrelle molto lisce possono diventare scivolose. L’erba all’aperto o i sentieri possono essere irregolari e umidi. Un tappetino rende più comodo il lavoro a terra ma può scivolare o comprimersi, quindi provalo prima di metterci sopra carichi pesanti.`},{title:`Scarpe adatte al compito`,text:`Scarpe stabili con una buona aderenza spesso funzionano bene per squat, hinge e movimenti laterali. Le scarpe da corsa ammortizzate possono essere comode per camminare o fare jogging, ma possono lasciare spostare il piede sotto sollevamenti pesanti. Le scarpe costruite per sport specifici sono diverse, e nessuno stile è il migliore per ogni esercizio o per ogni persona.`},{title:`L’allenamento a piedi nudi dipende dal contesto`,text:`Allenarsi a piedi nudi ti dà un riscontro diretto dal suolo in uno spazio pulito e sicuro, ma lascia i piedi esposti a pesi che cadono, oggetti appuntiti e altri pericoli. Alcune palestre non lo permettono. Se hai una sensibilità ridotta ai piedi, problemi di equilibrio o una condizione medica del piede, chiedi consiglio per la tua situazione prima di andare a piedi nudi, perché non è automaticamente meglio.`},{title:`Impatto e rumore`,text:`Salti e corsa producono più impatto e rumore di squat controllati o della marcia. Un tappetino di gomma può ridurre un po’ il suono, ma servono comunque una buona aderenza e un pavimento solido sotto. Evita calzini scivolosi, gommapiuma instabile sotto i pesi e tappetini che si increspano quando ti sposti di lato.`},{title:`Usare TrainUp`,text:`Imposta in Profilo la superficie e se saltare va bene, e il piano sceglie esercizi adatti. Se il pavimento è scivoloso o irregolare, scegli esercizi stabili a basso impatto oppure rimanda il movimento finché la superficie non è sicura.`}];var a=[{label:`Libreria di esercizi ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: sicurezza e tecnica dell’allenamento coi pesi`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Position stand ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var t={sections:o,sources:a};export{t as default,o as sections,a as sources};